  private static void l(String code) {
    if (d == null) {
      d = new Hashtable();
    } else {
      d.clear();
    }
    String[] vals;
    if ("he".equals(code)) {
      vals = HE.VALUES;
    }
    else if ("pl".equals(code)) {
      vals = PL.VALUES;
    }
    else if ("pt".equals(code)) {
      vals = PT.VALUES;
    }
    else if ("tr".equals(code)) {
      vals = TR.VALUES;
    }
    else if ("vi".equals(code)) {
      vals = VI.VALUES;
    }
    else {
      vals = EN.VALUES;
    }
    for (int j = 0; j < KEYS.length; j++) {
      d.put(KEYS[j], vals[j]);
    }
  }

  public static void setLang(String code) {
    if (!code.equals(c)) {
      c = code;
      l(code);
      i = true;
    }
  }

  public static String getCurrentLang() { return c; }

  public static String[] getAvailableLanguages() {
    return new String[] {"en", "he", "pl", "pt", "tr", "vi"};
  }

  public static String tr(String k) {
    if (!i) {
      l(c);
      i = true;
    }
    String v = (String) d.get(k);
    return v != null ? v : k;
  }

  public static String tr(String k, String a) {
    return Utils.replace(tr(k), "{0}", a);
  }

  private Lang() {}
